<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import { computed } from 'vue';

interface Attachment { id: number; original_name: string }
interface Item { id: number; type: string; description: string; amount: string; paid_amount: string | null; status: string; due_date: string | null; attachments: Attachment[] }
interface Quote { id: number; vendor_name: string; title: string; details: string | null; amount: string; valid_until: string | null; status: string }
const props = defineProps<{ wedding: { id: number; name: string }; items: Item[]; quotes: Quote[]; canManage: boolean }>();
const itemForm = useForm({ type: 'charge', description: '', amount: null as number | null, due_date: '', visible_to_couple: false, notes: '' });
const paymentForm = useForm({ amount: null as number | null, paid_at: new Date().toISOString().slice(0, 10), method: 'transfer', reference: '' });
const quoteForm = useForm({ vendor_name: '', title: '', details: '', amount: null as number | null, valid_until: '' });
const attachmentForm = useForm({ file: null as File | null });
const totals = computed(() => { const total = props.items.reduce((sum, item) => sum + Number(item.amount), 0); const paid = props.items.reduce((sum, item) => sum + Number(item.paid_amount ?? 0), 0); return { total, paid, balance: total - paid }; });
const money = (amount: number) => new Intl.NumberFormat('es-MX', { style: 'currency', currency: 'MXN' }).format(amount);
function addItem(): void { itemForm.post(route('weddings.finance.items.store', props.wedding.id), { preserveScroll: true, onSuccess: () => itemForm.reset() }); }
function addPayment(item: Item): void { paymentForm.post(route('weddings.finance.payments.store', [props.wedding.id, item.id]), { preserveScroll: true, onSuccess: () => paymentForm.reset() }); }
function addQuote(): void { quoteForm.post(route('weddings.finance.quotes.store', props.wedding.id), { preserveScroll: true, onSuccess: () => quoteForm.reset() }); }
function selectAttachment(event: Event): void { attachmentForm.file = (event.target as HTMLInputElement).files?.[0] ?? null; }
function uploadAttachment(item: Item): void { attachmentForm.post(route('weddings.finance.attachments.store', [props.wedding.id, item.id]), { forceFormData: true, preserveScroll: true, onSuccess: () => attachmentForm.reset() }); }
</script>

<template>
    <Head :title="`Finanzas · ${wedding.name}`" />
    <AuthenticatedLayout>
        <template #header><div><Link :href="route('weddings.workspace', wedding.id)" class="text-sm text-rose-800 underline">← Centro</Link><h1 class="mt-1 font-serif text-3xl">Finanzas</h1></div></template>
        <div class="mx-auto max-w-6xl space-y-6 px-4 py-8">
            <section class="grid gap-4 sm:grid-cols-3"><article class="rounded-2xl bg-stone-800 p-5 text-white"><p class="text-sm text-rose-100">Total registrado</p><p class="mt-1 text-2xl font-semibold">{{ money(totals.total) }}</p></article><article class="rounded-2xl border border-stone-200 bg-white p-5"><p class="text-sm text-stone-500">Pagado</p><p class="mt-1 text-2xl font-semibold text-stone-800">{{ money(totals.paid) }}</p></article><article class="rounded-2xl border border-stone-200 bg-white p-5"><p class="text-sm text-stone-500">Saldo</p><p class="mt-1 text-2xl font-semibold text-stone-800">{{ money(totals.balance) }}</p></article></section>
            <section class="rounded-2xl border border-stone-200 bg-white p-5"><h2 class="font-serif text-2xl">Conceptos y pagos</h2><article v-for="item in items" :key="item.id" class="mt-4 border-t border-stone-100 pt-4"><div class="flex flex-wrap items-start justify-between gap-3"><div><b>{{ item.description }}</b><p class="text-sm text-stone-600">{{ item.type === 'charge' ? 'Cobro a pareja' : 'Costo interno' }} · Importe {{ money(Number(item.amount)) }} · Pagado {{ money(Number(item.paid_amount ?? 0)) }} · {{ item.status }}</p></div><span class="rounded bg-stone-100 px-2 py-1 text-xs text-stone-600">{{ item.due_date || 'Sin vencimiento' }}</span></div><form v-if="canManage && item.status !== 'paid'" class="mt-3 flex flex-wrap gap-2" @submit.prevent="addPayment(item)"><input v-model.number="paymentForm.amount" type="number" min="0.01" step="0.01" required class="w-28 rounded border-stone-300" placeholder="Pago"><input v-model="paymentForm.paid_at" type="date" required class="rounded border-stone-300"><select v-model="paymentForm.method" class="rounded border-stone-300"><option value="transfer">Transferencia</option><option value="cash">Efectivo</option><option value="card">Tarjeta</option><option value="other">Otro</option></select><input v-model="paymentForm.reference" class="rounded border-stone-300" placeholder="Referencia"><button class="rounded border border-rose-700 px-3 py-1 text-sm text-rose-800">Registrar pago</button></form><div v-if="item.attachments.length" class="mt-3 text-sm"><p class="font-medium text-stone-700">Comprobantes privados</p><a v-for="attachment in item.attachments" :key="attachment.id" :href="route('weddings.finance.attachments.download', [wedding.id, attachment.id])" class="mr-3 inline-block text-rose-800 underline">{{ attachment.original_name }}</a></div><form v-if="canManage" class="mt-3 flex flex-wrap items-center gap-2" @submit.prevent="uploadAttachment(item)"><input type="file" accept=".pdf,.jpg,.jpeg,.png" required class="text-sm" @change="selectAttachment"><button :disabled="!attachmentForm.file || attachmentForm.processing" class="rounded border border-stone-400 px-3 py-1 text-sm text-stone-700 disabled:opacity-50">Adjuntar comprobante</button></form></article><p v-if="!items.length" class="mt-4 text-sm text-stone-500">No hay conceptos financieros todavía.</p><form v-if="canManage" class="mt-6 grid gap-3 rounded-xl bg-stone-50 p-4 md:grid-cols-2" @submit.prevent="addItem"><h3 class="font-serif text-xl md:col-span-2">Nuevo concepto</h3><select v-model="itemForm.type" class="rounded border-stone-300"><option value="charge">Cobro a pareja</option><option value="cost">Costo interno</option></select><input v-model="itemForm.description" required class="rounded border-stone-300" placeholder="Concepto"><input v-model.number="itemForm.amount" required type="number" min="0" step="0.01" class="rounded border-stone-300" placeholder="Importe"><input v-model="itemForm.due_date" type="date" class="rounded border-stone-300"><textarea v-model="itemForm.notes" class="rounded border-stone-300 md:col-span-2" placeholder="Notas internas"></textarea><label class="text-sm text-stone-700"><input v-model="itemForm.visible_to_couple" type="checkbox"> Visible a pareja</label><button class="justify-self-start rounded bg-rose-800 px-3 py-2 text-sm text-white">Agregar concepto</button></form></section>
            <section v-if="canManage" class="rounded-2xl border border-stone-200 bg-white p-5"><h2 class="font-serif text-2xl">Cotizaciones</h2><article v-for="quote in quotes" :key="quote.id" class="mt-3 rounded-xl bg-stone-50 p-4"><b>{{ quote.title }}</b><p class="text-sm text-stone-600">{{ quote.vendor_name }} · {{ money(Number(quote.amount)) }} · {{ quote.valid_until || 'Sin vigencia definida' }}</p><p v-if="quote.details" class="mt-1 text-sm text-stone-600">{{ quote.details }}</p></article><p v-if="!quotes.length" class="mt-3 text-sm text-stone-500">Aún no hay cotizaciones.</p><form class="mt-5 grid gap-3 rounded-xl bg-stone-50 p-4 md:grid-cols-2" @submit.prevent="addQuote"><h3 class="font-serif text-xl md:col-span-2">Registrar cotización</h3><input v-model="quoteForm.vendor_name" required class="rounded border-stone-300" placeholder="Proveedor"><input v-model="quoteForm.title" required class="rounded border-stone-300" placeholder="Concepto"><input v-model.number="quoteForm.amount" required type="number" min="0" step="0.01" class="rounded border-stone-300" placeholder="Importe"><input v-model="quoteForm.valid_until" type="date" class="rounded border-stone-300"><textarea v-model="quoteForm.details" class="rounded border-stone-300 md:col-span-2" placeholder="Alcance y condiciones"></textarea><button class="justify-self-start rounded bg-rose-800 px-3 py-2 text-sm text-white">Guardar cotización</button></form></section>
        </div>
    </AuthenticatedLayout>
</template>
